import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Ho.css";

function Archive() {
  const [generatedImages, setGeneratedImages] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    // Load generated images from localStorage
    const savedImages = localStorage.getItem('generatedImages');
    if (savedImages) {
      setGeneratedImages(JSON.parse(savedImages));
    }
  }, []);

  return (
    <div className="ho-container">
      <div className="ho-title-container">
        <h1 className="ho-title">Generated Archive</h1>
      </div>

      <div className="ho-main">
        <div className="box1">
        <h1 className="ho-list" onClick={() => navigate('/ho')} style={{ cursor: 'pointer' }}>Images</h1>
          <h1 className="ho-list" onClick={() => navigate('/archive')} style={{ cursor: 'pointer' }}>Archive</h1>
          <h1 className="ho-list" onClick={() => navigate('/about')} style={{ cursor: 'pointer' }}>About</h1>
        </div>

        <div className="ho-grid">
          {generatedImages.map((img, i) => (
            <div key={`generated-${i}`} className="ho-image-container">
              <img
                src={img.url}
                alt={`generated-${i}`}
                className="ho-image"
              />
              {img.timestamp && (
                <div className="ho-timestamp">
                  {new Date(img.timestamp).toLocaleString()}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Archive;
